  const DibaTheme._();

  static ThemeData light() => _theme(lightScheme);
  static ThemeData dark() => _theme(darkScheme);

  static const ColorScheme lightScheme = ColorScheme(
    brightness: Brightness.light,
    primary: DibaLightColors.primary,
    onPrimary: DibaLightColors.primaryFg,
    primaryContainer: DibaLightColors.primarySoft,
    onPrimaryContainer: DibaLightColors.primaryEmphasis,
    secondary: DibaLightColors.accent,
    onSecondary: DibaLightColors.accentFg,
    secondaryContainer: DibaLightColors.accentSoft,
    onSecondaryContainer: DibaLightColors.accentEmphasis,
    error: DibaLightColors.danger,
    onError: DibaLightColors.dangerFg,
    surface: DibaLightNeutrals.surface,
    onSurface: DibaLightNeutrals.foreground,
    onSurfaceVariant: DibaLightNeutrals.muted,
    surfaceContainerLowest: DibaLightNeutrals.surface,
    // The page, which the scaffold paints.
    surfaceContainerLow: DibaLightNeutrals.background,
    surfaceContainer: DibaLightNeutrals.surfaceSecondary,
    surfaceContainerHigh: DibaLightNeutrals.surfaceSecondary,
    // The third surface, so "a darker grey" has somewhere to come from.
