    outline: DibaLightNeutrals.outline,
    outlineVariant: DibaLightNeutrals.border,
    scrim: DibaLightColors.overlay,
    shadow: DibaLightNeutrals.foreground,
    inverseSurface: DibaLightNeutrals.foreground,
    onInverseSurface: DibaLightNeutrals.background,
