  static const ColorScheme darkScheme = ColorScheme(
    brightness: Brightness.dark,
    primary: DibaDarkColors.primary,
    onPrimary: DibaDarkColors.primaryFg,
    primaryContainer: DibaDarkColors.primarySoft,
    onPrimaryContainer: DibaDarkColors.primaryEmphasis,
    secondary: DibaDarkColors.accent,
