        dark ? DibaDarkColors.plainHover : DibaLightColors.plainHover;

    // A field's edge and placeholder are the web's field roles. In dark
    // the edge is the slate-700 hairline, one step lighter than the border
    // between other things.
    final Color fieldBorder =
        dark ? DibaDarkNeutrals.fieldBorder : DibaLightNeutrals.fieldBorder;
    final Color placeholder =
        dark ? DibaDarkNeutrals.placeholder : DibaLightNeutrals.placeholder;

    return ThemeData(
      useMaterial3: true,
      // Diba's sizes are tokens. Flutter's adaptive default is compact on
      // desktop and the web, which takes eight pixels off every field and button there
      // and nowhere else.
      visualDensity: VisualDensity.standard,
      colorScheme: scheme,
      scaffoldBackgroundColor: scheme.surfaceContainerLow,
      // The washes Material draws over a control hovered, focused and pressed:
      // its own defaults, as tokens, so the web's tags take the same.
      hoverColor: dark ? DibaDarkColors.stateHover : DibaLightColors.stateHover,
      focusColor: dark ? DibaDarkColors.stateFocus : DibaLightColors.stateFocus,
      highlightColor:
          dark ? DibaDarkColors.statePress : DibaLightColors.statePress,
      extensions: <ThemeExtension<dynamic>>[
        scheme.brightness == Brightness.dark
            ? DibaStatusColors.dark
            : DibaStatusColors.light,
      ],
      // Persian first. Yekan Bakh must be declared in pubspec.yaml under this
      // exact family name, with Inter as the Latin fallback inside the font
      // declaration rather than here — Flutter takes one family per style.
      fontFamily: DibaFonts.fa,
      textTheme: _textTheme(scheme.onSurface),
      // The caret is the text colour, as a browser draws it; Material's
      // default is primary, the gilt, at 1.75:1 on a white field. The handles
      // follow the caret. The selection highlight is left to Material.
      textSelectionTheme: TextSelectionThemeData(
        cursorColor: scheme.onSurface,
        selectionHandleColor: scheme.onSurface,
      ),

      // ---- fields ------------------------------------------------------------

      // Every edge is drawn outside the field, as the web draws its hairline
      // as a shadow and its focus ring round it, so the field keeps its size
      // in every state.
      inputDecorationTheme: InputDecorationTheme(
        border: _fieldEdge(fieldBorder),
        enabledBorder: _fieldEdge(fieldBorder),
        // Focus is Diba's ring. An invalid field draws its edge, and its
        // ring, in the error colour.
        focusedBorder: _fieldEdge(ring, DibaDimens.focusWidth),
        errorBorder: _fieldEdge(scheme.error),
        focusedErrorBorder: _fieldEdge(scheme.error, DibaDimens.focusWidth),
        // Half the enabled edge, as the web's whole field fades when disabled.
        // Left unset, Material fell back to `border` and a disabled field
        // looked the more present.
        disabledBorder: _fieldEdge(fieldBorder.withValues(alpha: 0.5)),
        // The ring marks focus; the label keeps the text colour.
        floatingLabelStyle: TextStyle(color: scheme.onSurface),
        hintStyle: TextStyle(color: placeholder),
      ),

      // ---- surfaces: v3's overlays are white --------------------------------
      //
      // Material paints dialogs, sheets, menus and pickers surfaceContainerHigh,
      // which here is surface-2, a grey. The admin's are white.

      dialogTheme: DialogThemeData(
        backgroundColor: scheme.surface,
        // Material's dialogs, the time picker's among them, over the web's backdrop as Diba's
        // own are, where Flutter had put them on black at 54%.
        barrierColor: scheme.scrim,
        surfaceTintColor: const Color(0x00000000),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(DibaDimens.modalRadius),
        ),
      ),
      bottomSheetTheme: BottomSheetThemeData(
        backgroundColor: scheme.surface,
        modalBackgroundColor: scheme.surface,
        surfaceTintColor: const Color(0x00000000),
      ),
      // The picked day, and the picked year, are gilt with the colour on gilt,
      // as the choices are. Material's own text on them was the iris.
      datePickerTheme: DatePickerThemeData(
        backgroundColor: scheme.surface,
        surfaceTintColor: const Color(0x00000000),
        dayBackgroundColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlFill : null,
        ),
        dayForegroundColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlOnFill : null,
        ),
        todayBackgroundColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlFill : null,
        ),
        todayForegroundColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlOnFill : null,
        ),
        yearBackgroundColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlFill : null,
        ),
        yearForegroundColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlOnFill : null,
        ),
      ),
      // The selected AM/PM was the copper. It takes the text colour, with
      // the surface's colour on it.
      timePickerTheme: TimePickerThemeData(
        backgroundColor: scheme.surface,
        dayPeriodColor: WidgetStateColor.resolveWith(
          (states) => states.contains(WidgetState.selected)
              ? scheme.onSurface
              : const Color(0x00000000),
        ),
        dayPeriodTextColor: WidgetStateColor.resolveWith(
          (states) => states.contains(WidgetState.selected)
              ? scheme.surface
              : scheme.onSurfaceVariant,
        ),
      ),
      menuTheme: MenuThemeData(
        style: MenuStyle(backgroundColor: WidgetStatePropertyAll(scheme.surface)),
      ),
      dropdownMenuTheme: DropdownMenuThemeData(
        menuStyle: MenuStyle(backgroundColor: WidgetStatePropertyAll(scheme.surface)),
      ),

      sliderTheme: SliderThemeData(
        activeTrackColor: controlFill,
        thumbColor: controlOnFill,
        inactiveTrackColor: controlTrack,
        activeTickMarkColor: controlOnFill,
        inactiveTickMarkColor: controlThumbOff,
        valueIndicatorColor: controlOnFill,
        // Flutter's own slider, on both platforms: the thin track, the
        // round thumb and the step dots stay. The thumb gains a gilt ring.
        thumbShape: DibaRingedThumbShape(ring: controlFill),
        rangeThumbShape: DibaRingedRangeThumbShape(ring: controlFill),
        // Laid out as the web's: as
        // high as its thumb, 20, where Flutter's was its 48 state layer, and
        // its track half a thumb in from each end, where Flutter's was 24.
        padding: EdgeInsets.zero,
        trackShape: const DibaSliderTrackShape(),
        rangeTrackShape: const DibaRangeSliderTrackShape(),
        // A disabled slider fades as a whole, keeping its colours, as the
        // web's does; Flutter greyed it.
        disabledActiveTrackColor: controlFill,
        disabledInactiveTrackColor: controlTrack,
        disabledThumbColor: controlOnFill,
        disabledActiveTickMarkColor: controlOnFill,
        disabledInactiveTickMarkColor: controlThumbOff,
        // The value shows beside the label, as the web shows it, and nowhere
        // else: no bubble over the thumb while it is dragged.
        showValueIndicator: ShowValueIndicator.never,
      ),

      // Diba's tooltip, the web's: the overlay's paper and shadow (in dark, its faint
      // inner edge), 12 on a 16 line, 8 round it, 12 round its corners, above
      // its target after half a second, and gone half a second after the
      // pointer leaves. Material's was a grey bubble, below, at once. A button
      // that shows only its icon adds the web's arrow (actions.dart).
      tooltipTheme: TooltipThemeData(
        decoration: overlay(dark: dark, radius: 12),
        textStyle: TextStyle(
          fontFamily: DibaFonts.fa,
          fontSize: 12,
          height: 16 / 12,
          letterSpacing: 0,
          color: dark ? DibaDarkNeutrals.foreground : DibaLightNeutrals.foreground,
        ),
        padding: const EdgeInsets.all(8),
        preferBelow: false,
        verticalOffset: 28,
        waitDuration: const Duration(milliseconds: 500),
        exitDuration: const Duration(milliseconds: 500),
      ),

      progressIndicatorTheme: ProgressIndicatorThemeData(
        color: controlFill,
        linearTrackColor: controlTrack,
        circularTrackColor: controlTrack,
      ),

      // v3's segment pill: the selected tab is a pill in `segment`, on
      // the list that DibaTabList draws behind the bar, since a theme cannot.
      // The light pill takes v3's field shadow. The dark one has none, and is
      // slate-700 on a slate-800 list, so it can be seen. The labels keep
      // Material's titleSmall, which is already the medium weight at the sm size.
      //
      // `TabBarThemeData` is the current type of ThemeData.tabBarTheme. It was
      // `TabBarTheme` until Flutter 3.27 — if you pin an older SDK, this one
      // identifier is the only thing to rename.
      tabBarTheme: TabBarThemeData(
        indicator: ShapeDecoration(
          shape: const StadiumBorder(),
          color: segment,
          shadows: dark ? const <BoxShadow>[] : _segmentShadow,
        ),
        indicatorSize: TabBarIndicatorSize.tab,
        dividerHeight: 0,
        labelColor: segmentFg,
        unselectedLabelColor: segmentFgMuted,
        labelPadding: EdgeInsets.symmetric(horizontal: DibaSpace.space4),
        overlayColor: const WidgetStatePropertyAll(Color(0x00000000)),
        splashFactory: NoSplash.splashFactory,
      ),

      // secondaryContainer, following Material, rather than primaryContainer:
      // primary-soft is saffron.50, which against a near-white surface is not a
      // pill so much as a rumour. Selection still reads either way, because the
      // icon and label go to onSecondaryContainer — a strong iris — but there is
      // no reason to pick the paler of the two.
      navigationBarTheme: NavigationBarThemeData(
        indicatorColor: scheme.secondaryContainer,
        backgroundColor: scheme.surface,
      ),

      // A checked box, a radio and a switch take the choices' roles. The tick, the
      // dot and an on thumb sit on the gilt, so they are slate-700 in both
      // themes: 5.88:1 against it. An unchecked box keeps the outline it had.
      checkboxTheme: CheckboxThemeData(
        fillColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlFill : null,
        ),
        checkColor: WidgetStateProperty.all(controlOnFill),
      ),
      // Material draws a radio's ring and dot in one colour. A selected radio
      // here is a gilt disc with a slate dot, as the web draws it: the
      // background and the ring are the gilt, the fill (the dot) the slate.
      radioTheme: RadioThemeData(
        fillColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlOnFill : scheme.outline,
        ),
        backgroundColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlFill : null,
        ),
        side: WidgetStateBorderSide.resolveWith(
          (states) => BorderSide(
            color: states.contains(WidgetState.selected) ? controlFill : scheme.outline,
            width: 2,
          ),
        ),
      ),
      switchTheme: SwitchThemeData(
        trackColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlFill : controlTrack,
        ),
        thumbColor: WidgetStateProperty.resolveWith(
          (states) => states.contains(WidgetState.selected) ? controlOnFill : controlThumbOff,
        ),
        // No outline: the off track is a filled slate, as on the web.
        trackOutlineColor: const WidgetStatePropertyAll(Color(0x00000000)),
      ),

      // ---- shape ------------------------------------------------------------

      // Pills, as v3's buttons are. Fields keep their DibaRadius.md, above.
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(
          minimumSize: Size(0, DibaDimens.controlHeightMd),
          padding: EdgeInsets.symmetric(horizontal: DibaDimens.controlPxMd),
          shape: const StadiumBorder(),
        ),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          minimumSize: Size(0, DibaDimens.controlHeightMd),
          padding: EdgeInsets.symmetric(horizontal: DibaDimens.controlPxMd),
          shape: const StadiumBorder(),
        ),
      ),
      // A plain text button, such as a dialog's action, is v3's ghost:
      // the secondary button's text, and its background under a hover, a press
      // or keyboard focus. The renderer's ghost Button sets its own ink.
      textButtonTheme: TextButtonThemeData(
        style: TextButton.styleFrom(
          foregroundColor: plainFg,
          shape: const StadiumBorder(),
        ).copyWith(
          overlayColor: WidgetStateProperty.resolveWith(
            (states) => states.contains(WidgetState.hovered) ||
                    states.contains(WidgetState.pressed) ||
                    states.contains(WidgetState.focused)
                ? plainHover
                : null,
          ),
        ),
      ),
    );
  }

  /// v3's field shadow, under the light theme's tab pill. Diba's shadow
  /// tokens are emitted for CSS only, so this is the one shadow written here.
  static const List<BoxShadow> _segmentShadow = <BoxShadow>[
    BoxShadow(color: Color(0x0A000000), offset: Offset(0, 2), blurRadius: 4),
    BoxShadow(color: Color(0x0F000000), offset: Offset(0, 1), blurRadius: 2),
    BoxShadow(color: Color(0x0F000000), blurRadius: 1),
  ];

  /// The web's overlay shadow in light (`--overlay-shadow`), under a tooltip.
  /// A CSS blur of b is a sigma of b / 2, and Flutter's blur radius r a sigma
  /// of 0.57735r + 0.5, so each blur is converted.
  static final List<BoxShadow> _overlayShadow = <BoxShadow>[
    BoxShadow(color: const Color(0x0F000000), offset: const Offset(0, 2), blurRadius: _cssBlur(8)),
    BoxShadow(color: const Color(0x08000000), offset: const Offset(0, -6), blurRadius: _cssBlur(12)),
    BoxShadow(color: const Color(0x14000000), offset: const Offset(0, 14), blurRadius: _cssBlur(28)),
  ];

  static double _cssBlur(double b) => (b / 2 - 0.5) / 0.57735;

  /// The web's card shadow (`--surface-shadow`) in light, three soft layers;
  /// in dark a card has none, as the web's has none.
  static List<BoxShadow> surfaceShadow({required bool dark}) => dark
      ? const <BoxShadow>[]
      : <BoxShadow>[
          BoxShadow(color: const Color(0x0A000000), offset: const Offset(0, 2), blurRadius: _cssBlur(4)),
          BoxShadow(color: const Color(0x0F000000), offset: const Offset(0, 1), blurRadius: _cssBlur(2)),
          BoxShadow(color: const Color(0x0F000000), blurRadius: _cssBlur(1)),
        ];

  /// The web's overlay (`bg-overlay` with `--overlay-shadow`), as a tooltip
  /// or a menu draws it: the surface, with the overlay shadow in light, and in
  /// dark a hairline of white at 15% for the web's inset glow.
  static ShapeDecoration overlay({required bool dark, required double radius}) =>
      ShapeDecoration(
        color: dark ? DibaDarkNeutrals.surface : DibaLightNeutrals.surface,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.all(Radius.circular(radius)),
          side: dark ? const BorderSide(color: Color(0x26FFFFFF)) : BorderSide.none,
        ),
        shadows: dark ? const <BoxShadow>[] : _overlayShadow,
      );

  /// A field's edge in [color], [width] thick, outside the field. No gap: M3
  /// insets an outlined field's text by the gap its floating label cuts in the
  /// edge, 4 past its padding, and a Diba field's label is above it.
  static OutlineInputBorder _fieldEdge(Color color, [double width = 1]) =>
      OutlineInputBorder(
        borderRadius: BorderRadius.circular(DibaRadius.md),
        gapPadding: 0,
        borderSide: BorderSide(
          color: color,
          width: width,
          strokeAlign: BorderSide.strokeAlignOutside,
        ),
      );

  /// Material's type roles, on Diba's scale.
  ///
  /// Line heights come from the tokens rather than Material's defaults, which
  /// are set for Latin and run tight under Persian — the ascenders and the
  /// nastaliq-influenced descenders in Yekan Bakh need the extra room.
  ///
  /// None of Material's letter spacing (0.1 to 0.5 by role), which the theme
  /// merges in under these unless they say otherwise: the web sets none, and
  /// Flutter's text ran visibly wider than the web's.
  static TextTheme _textTheme(Color ink) {
    TextStyle s(double size, FontWeight weight, double height) => TextStyle(
      fontSize: size,
      fontWeight: weight,
      height: height,
      letterSpacing: 0,
      color: ink,
    );

    return TextTheme(
      headlineLarge: s(DibaFontSize.text2xl, DibaFontWeight.bold, DibaLineHeight.tight),
      headlineMedium: s(DibaFontSize.xl, DibaFontWeight.bold, DibaLineHeight.tight),
      headlineSmall: s(DibaFontSize.lg, DibaFontWeight.semibold, DibaLineHeight.snug),
      titleLarge: s(DibaFontSize.lg, DibaFontWeight.semibold, DibaLineHeight.snug),
      titleMedium: s(DibaFontSize.md, DibaFontWeight.semibold, DibaLineHeight.snug),
      titleSmall: s(DibaFontSize.sm, DibaFontWeight.medium, DibaLineHeight.snug),
      bodyLarge: s(DibaFontSize.md, DibaFontWeight.normal, DibaLineHeight.normal),
      bodyMedium: s(DibaFontSize.sm, DibaFontWeight.normal, DibaLineHeight.normal),
      bodySmall: s(DibaFontSize.xs, DibaFontWeight.normal, DibaLineHeight.normal),
      labelLarge: s(DibaFontSize.sm, DibaFontWeight.medium, DibaLineHeight.snug),
      labelMedium: s(DibaFontSize.xs, DibaFontWeight.medium, DibaLineHeight.snug),
      labelSmall: s(DibaFontSize.xs, DibaFontWeight.medium, DibaLineHeight.snug),
    );
  }
}

/// One colour word in the four strengths a block needs.
@immutable
class DibaStatusTone {
  const DibaStatusTone({
    required this.solid,
    required this.onSolid,
    required this.soft,
    required this.ink,
  });

  /// A fill: a solid chip, a filled button, a progress bar.
  final Color solid;

  /// Text and icons on [solid].
  final Color onSolid;

  /// A tinted background: an alert, a soft chip.
  final Color soft;

  /// Text and icons on a surface or on [soft]: the emphasis step, which holds
  /// contrast where the fill colour would not.
  final Color ink;

  static DibaStatusTone lerp(DibaStatusTone a, DibaStatusTone b, double t) =>
      DibaStatusTone(
        solid: Color.lerp(a.solid, b.solid, t)!,
        onSolid: Color.lerp(a.onSolid, b.onSolid, t)!,
        soft: Color.lerp(a.soft, b.soft, t)!,
        ink: Color.lerp(a.ink, b.ink, t)!,
      );
}

/// v3's colour words (default, accent, success, warning, danger) as a
/// ThemeExtension, because Material's ColorScheme has no success, warning or
/// info role at all.
///
/// `accent` is the brand, the gilt primary: the admin maps `--accent` to
/// `--db-primary`. Diba's own token named accent, the iris, is the scheme's
/// `secondary`, and is not this.
///
/// The soft strengths of success, warning, danger and info are not tokens yet.
/// They are the solid colour at 12% (22% in the dark theme) over the surface.
@immutable
class DibaStatusColors extends ThemeExtension<DibaStatusColors> {
  const DibaStatusColors({
    required this.neutral,
    required this.accent,
    required this.success,
    required this.warning,
    required this.danger,
    required this.info,
  });

  /// The word `default`, which Dart cannot use as a name.
  final DibaStatusTone neutral;
  final DibaStatusTone accent;
  final DibaStatusTone success;
  final DibaStatusTone warning;
  final DibaStatusTone danger;
  final DibaStatusTone info;

  /// The tone for a colour word from a tree; anything unknown is default.
  DibaStatusTone of(String? word) => switch (word) {
    'accent' => accent,
    'success' => success,
    'warning' => warning,
    'danger' => danger,
    'info' => info,
    _ => neutral,
  };

  static Color _soft(Color colour, Color surface, double alpha) =>
      Color.alphaBlend(colour.withValues(alpha: alpha), surface);

  static final DibaStatusColors light = DibaStatusColors(
    // The web's default: `--default` with its own text.
    neutral: const DibaStatusTone(
      solid: DibaLightNeutrals.fill,
      onSolid: DibaLightNeutrals.fillForeground,
      soft: DibaLightNeutrals.surfaceSecondary,
      ink: DibaLightNeutrals.foreground,
    ),
    accent: const DibaStatusTone(
      solid: DibaLightColors.primary,
      onSolid: DibaLightColors.primaryFg,
      soft: DibaLightColors.primarySoft,
      ink: DibaLightColors.primaryEmphasis,
    ),
    success: DibaStatusTone(
      solid: DibaLightColors.success,
      onSolid: DibaLightColors.successFg,
      soft: _soft(DibaLightColors.success, DibaLightNeutrals.surface, 0.12),
      ink: DibaLightColors.successEmphasis,
    ),
    warning: DibaStatusTone(
      solid: DibaLightColors.warning,
      onSolid: DibaLightColors.warningFg,
      soft: _soft(DibaLightColors.warning, DibaLightNeutrals.surface, 0.12),
      ink: DibaLightColors.warningEmphasis,
    ),
    danger: DibaStatusTone(
      solid: DibaLightColors.danger,
      onSolid: DibaLightColors.dangerFg,
      soft: _soft(DibaLightColors.danger, DibaLightNeutrals.surface, 0.12),
      ink: DibaLightColors.dangerEmphasis,
    ),
    info: DibaStatusTone(
      solid: DibaLightColors.info,
      onSolid: DibaLightColors.infoFg,
      soft: _soft(DibaLightColors.info, DibaLightNeutrals.surface, 0.12),
      ink: DibaLightColors.infoEmphasis,
    ),
  );

  static final DibaStatusColors dark = DibaStatusColors(
    neutral: const DibaStatusTone(
      solid: DibaDarkNeutrals.fill,
      onSolid: DibaDarkNeutrals.fillForeground,
      soft: DibaDarkNeutrals.surfaceSecondary,
      ink: DibaDarkNeutrals.foreground,
    ),
    accent: const DibaStatusTone(
      solid: DibaDarkColors.primary,
      onSolid: DibaDarkColors.primaryFg,
      soft: DibaDarkColors.primarySoft,
      ink: DibaDarkColors.primaryEmphasis,
    ),
    success: DibaStatusTone(
      solid: DibaDarkColors.success,
      onSolid: DibaDarkColors.successFg,
      soft: _soft(DibaDarkColors.success, DibaDarkNeutrals.surface, 0.22),
      ink: DibaDarkColors.successEmphasis,
    ),
    warning: DibaStatusTone(
      solid: DibaDarkColors.warning,
      onSolid: DibaDarkColors.warningFg,
      soft: _soft(DibaDarkColors.warning, DibaDarkNeutrals.surface, 0.22),
      ink: DibaDarkColors.warningEmphasis,
    ),
    danger: DibaStatusTone(
      solid: DibaDarkColors.danger,
      onSolid: DibaDarkColors.dangerFg,
      soft: _soft(DibaDarkColors.danger, DibaDarkNeutrals.surface, 0.22),
      ink: DibaDarkColors.dangerEmphasis,
    ),
    info: DibaStatusTone(
      solid: DibaDarkColors.info,
      onSolid: DibaDarkColors.infoFg,
      soft: _soft(DibaDarkColors.info, DibaDarkNeutrals.surface, 0.22),
      ink: DibaDarkColors.infoEmphasis,
    ),
  );

  @override
  DibaStatusColors copyWith({
    DibaStatusTone? neutral,
    DibaStatusTone? accent,
    DibaStatusTone? success,
    DibaStatusTone? warning,
    DibaStatusTone? danger,
    DibaStatusTone? info,
  }) => DibaStatusColors(
    neutral: neutral ?? this.neutral,
    accent: accent ?? this.accent,
    success: success ?? this.success,
    warning: warning ?? this.warning,
    danger: danger ?? this.danger,
    info: info ?? this.info,
  );

  @override
  DibaStatusColors lerp(DibaStatusColors? other, double t) {
    if (other == null) return this;
    return DibaStatusColors(
      neutral: DibaStatusTone.lerp(neutral, other.neutral, t),
      accent: DibaStatusTone.lerp(accent, other.accent, t),
      success: DibaStatusTone.lerp(success, other.success, t),
      warning: DibaStatusTone.lerp(warning, other.warning, t),
      danger: DibaStatusTone.lerp(danger, other.danger, t),
      info: DibaStatusTone.lerp(info, other.info, t),
    );
  }
}

/// The width of the slider thumb's gilt ring: 3. The web's `--slider-thumb-ring` is the same.
const double _thumbRingWidth = 3;

/// Flutter's round slider thumb with a ring inside its edge, so it keeps
/// its size: the ring is [_thumbRingWidth] wide inside the 20-wide thumb,
/// which leaves a slate core 14 across.
///
/// The thumb is slate-700, the colour on the gilt, in both themes, and half of
/// it sits on the empty track. In the dark theme that track is slate-700 too,
/// and without the ring the thumb vanished into it (1.00:1). The gilt ring is
/// 5.88:1 against that track and 9.14:1 against the dark card.
///
/// A disabled thumb keeps its colours: the slider fades as a whole, as the
/// web's does.
class DibaRingedThumbShape extends RoundSliderThumbShape {
  const DibaRingedThumbShape({
    required this.ring,
    this.ringWidth = _thumbRingWidth,
  });

  final Color ring;
  final double ringWidth;

  @override
  void paint(
    PaintingContext context,
    Offset center, {
    required Animation<double> activationAnimation,
    required Animation<double> enableAnimation,
    required bool isDiscrete,
    required TextPainter labelPainter,
    required RenderBox parentBox,
    required SliderThemeData sliderTheme,
    required TextDirection textDirection,
    required double value,
    required double textScaleFactor,
    required Size sizeWithOverflow,
  }) {
    _paintRingedThumb(
      context.canvas,
      center,
      enableAnimation: enableAnimation,
      sliderTheme: sliderTheme,
      ring: ring,
      ringWidth: ringWidth,
      radius: enabledThumbRadius,
      disabledRadius: disabledThumbRadius,
    );
  }
}

/// [DibaRingedThumbShape] for a range slider's two thumbs.
class DibaRingedRangeThumbShape extends RoundRangeSliderThumbShape {
  const DibaRingedRangeThumbShape({
    required this.ring,
    this.ringWidth = _thumbRingWidth,
  });

  final Color ring;
  final double ringWidth;

  @override
  void paint(
    PaintingContext context,
    Offset center, {
    required Animation<double> activationAnimation,
    required Animation<double> enableAnimation,
    bool isDiscrete = false,
    bool isEnabled = false,
    bool? isOnTop,
    TextDirection? textDirection,
    required SliderThemeData sliderTheme,
    Thumb? thumb,
    bool? isPressed,
  }) {
    _paintRingedThumb(
      context.canvas,
      center,
      enableAnimation: enableAnimation,
      sliderTheme: sliderTheme,
      ring: ring,
      ringWidth: ringWidth,
      radius: enabledThumbRadius,
      disabledRadius: disabledThumbRadius,
    );
  }
}

/// The thumb as the web draws it: the web's shadow ("0 1px 2px" at 30%), a
/// gilt disc, and the slate core on it. Flutter's own round thumb, with this
/// ring stroked over it, left the slate disc's edge showing round the ring as
/// a thin dark outline, and drew Flutter's sharper elevation shadow, deeper
/// while dragged. So the
/// thumb is painted whole here, and the same at rest and dragged, enabled or
/// not.
void _paintRingedThumb(
  Canvas canvas,
  Offset center, {
  required Animation<double> enableAnimation,
  required SliderThemeData sliderTheme,
  required Color ring,
  required double ringWidth,
  required double radius,
  required double? disabledRadius,
}) {
  final double r = Tween<double>(
    begin: disabledRadius ?? radius,
    end: radius,
  ).evaluate(enableAnimation);
  final Color core = Color.lerp(
    sliderTheme.disabledThumbColor ?? sliderTheme.thumbColor,
    sliderTheme.thumbColor,
    enableAnimation.value,
  )!;
  // A CSS blur of 2 is a sigma of 1.
  canvas.drawCircle(
    center.translate(0, 1),
    r,
    Paint()
      ..color = const Color.fromRGBO(0, 0, 0, 0.3)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 1),
  );
  canvas.drawCircle(center, r, Paint()..color = ring);
  canvas.drawCircle(center, r - ringWidth, Paint()..color = core);
}

/// The track as the web draws it:
/// between the thumb's furthest centres, half a thumb in from each end of the
/// slider, 4 high, with the fill 6 high from its start to the thumb, both
/// round at their ends. Flutter's ran from its state layer's edge, 24 in.
///
/// A stepped slider places its thumb and its dots half the track's height in
/// from the rect given here, so for one the rect reaches that much further
/// out: thumb and dots land where a smooth slider's thumb does, and the track
/// is drawn in the same place either way.
class DibaSliderTrackShape extends SliderTrackShape {
  const DibaSliderTrackShape();

  @override
  bool get isRounded => true;

  @override
  Rect getPreferredRect({
    required RenderBox parentBox,
    Offset offset = Offset.zero,
    required SliderThemeData sliderTheme,
    bool isEnabled = false,
    bool isDiscrete = false,
  }) => _thumbRun(
    parentBox.size,
    offset,
    sliderTheme,
    sliderTheme.thumbShape!.getPreferredSize(isEnabled, isDiscrete).width,
    stepped: isDiscrete,
  );

  @override
  void paint(
    PaintingContext context,
    Offset offset, {
    required RenderBox parentBox,
    required SliderThemeData sliderTheme,
    required Animation<double> enableAnimation,
    required Offset thumbCenter,
    Offset? secondaryOffset,
    bool isEnabled = false,
    bool isDiscrete = false,
    required TextDirection textDirection,
  }) {
    final Rect track = _thumbRun(
      parentBox.size,
      offset,
      sliderTheme,
      sliderTheme.thumbShape!.getPreferredSize(isEnabled, isDiscrete).width,
    );
    _paintTrack(
      context.canvas,
      track,
      sliderTheme,
      enableAnimation,
      from: textDirection == TextDirection.ltr ? track.left : track.right,
      to: thumbCenter.dx,
    );
  }
}

/// [DibaSliderTrackShape] for a range slider: the fill between its thumbs.
class DibaRangeSliderTrackShape extends RangeSliderTrackShape {
  const DibaRangeSliderTrackShape();

  @override
  bool get isRounded => true;

  @override
  Rect getPreferredRect({
    required RenderBox parentBox,
    Offset offset = Offset.zero,
    required SliderThemeData sliderTheme,
    bool isEnabled = false,
    bool isDiscrete = false,
  }) => _thumbRun(
    parentBox.size,
    offset,
    sliderTheme,
    sliderTheme.rangeThumbShape!.getPreferredSize(isEnabled, isDiscrete).width,
    stepped: isDiscrete,
  );

  @override
  void paint(
    PaintingContext context,
    Offset offset, {
    required RenderBox parentBox,
    required SliderThemeData sliderTheme,
    required Animation<double> enableAnimation,
    required Offset startThumbCenter,
    required Offset endThumbCenter,
    bool isEnabled = false,
    bool isDiscrete = false,
    required TextDirection textDirection,
  }) {
    _paintTrack(
      context.canvas,
      _thumbRun(
        parentBox.size,
        offset,
        sliderTheme,
        sliderTheme.rangeThumbShape!.getPreferredSize(isEnabled, isDiscrete).width,
      ),
      sliderTheme,
      enableAnimation,
      from: startThumbCenter.dx,
      to: endThumbCenter.dx,
    );
  }
}

/// Where a thumb's centre runs: half a thumb in from each end of a slider
/// [size] wide, at the track's height across its middle; for a [stepped]
/// slider, half the track's height further out (see [DibaSliderTrackShape]).
Rect _thumbRun(
  Size size,
  Offset offset,
  SliderThemeData sliderTheme,
  double thumbWidth, {
  bool stepped = false,
}) {
  final double height = sliderTheme.trackHeight!;
  final double inset = thumbWidth / 2 - (stepped ? height / 2 : 0);
  final double top = offset.dy + (size.height - height) / 2;
  return Rect.fromLTRB(
    offset.dx + inset,
    top,
    offset.dx + size.width - inset,
    top + height,
  );
}

/// The track, round at its ends, and on it the fill, 2 higher, from [from] to
/// [to], round at its ends too, as the web's are.
void _paintTrack(
  Canvas canvas,
  Rect track,
  SliderThemeData sliderTheme,
  Animation<double> enableAnimation, {
  required double from,
  required double to,
}) {
  final Color off = ColorTween(
    begin: sliderTheme.disabledInactiveTrackColor,
    end: sliderTheme.inactiveTrackColor,
  ).evaluate(enableAnimation)!;
  final Color on = ColorTween(
    begin: sliderTheme.disabledActiveTrackColor,
    end: sliderTheme.activeTrackColor,
  ).evaluate(enableAnimation)!;
  canvas.drawRRect(
    RRect.fromRectAndRadius(track, Radius.circular(track.height / 2)),
    Paint()..color = off,
  );
  final Rect fill = Rect.fromPoints(
    Offset(from, track.top - 1),
    Offset(to, track.bottom + 1),
  );
  if (fill.width > 0) {
    canvas.drawRRect(
      RRect.fromRectAndRadius(fill, Radius.circular(fill.height / 2)),
      Paint()..color = on,
    );
  }
}
